import gurobipy
from gurobipy import GRB

def solve_problem():
    data = CSVQA_DATA
    table = next((t for t in data['tables'] if t['table_id'] == 'file_0_view_0'))
    records = table['records']
    P = set()
    c_p = {}
    v_p = {}
    for rec in records:
        vals = rec['values']
        pid = vals['Project ID']
        P.add(pid)
        c_p[pid] = float(vals['Capital (k$)'])
        v_p[pid] = float(vals['NPV (k$)'])
    required = {'1', '4', '5', '6', '7', '10'}
    missing = required - P
    if missing:
        raise ValueError(f"Missing project IDs in data: {', '.join(sorted(missing))}")
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    y = m.addVars(P, vtype=GRB.BINARY, name='')
    m.setObjective(gurobipy.quicksum((v_p[p] * y[p] for p in P)), GRB.MAXIMIZE)
    m.addConstr(gurobipy.quicksum((c_p[p] * y[p] for p in P)) <= 1000, name='budget')
    m.addConstr(y['4'] + y['7'] <= 1, name='mutually_exclusive')
    m.addConstr(y['6'] <= y['1'], name='prerequisite')
    m.addConstr(y['10'] <= y['5'], name='contingent')
    m.optimize()
    return m
m = solve_problem()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
